// app.js
// ⚠️  Updated for security, stability, and future extensibility

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { validationResult, query } = require('express-validator');

const app = express();

/**
 *  Middleware – Security
 */
app.use(helmet());                      // Sets many secure HTTP headers
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || 'https://example.com', // tighten as needed
    methods: ['GET', 'POST', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: false,
  })
);

/**
 *  Middleware – Common
 */
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse URL‑encoded bodies

/**
 *  Middleware – Rate limiting
 *  You can tweak `max` / `windowMs` for your traffic profile
 */
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 200,                 // limit each IP to 200 requests per windowMs
    standardHeaders: true,    // Return rate limit info in the `RateLimit-*` headers
    legacyHeaders: false,     // Don’t use the `X‑RateLimit-*` headers
    message: { error: 'Too many requests, please try again later.' },
  })
);

/**
 *  Routes
 */

// Health check – simple JSON status
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime() + 's',
    });
  } catch (err) {
    next(err); // forward to error handler
  }
});

/**
 *  Example: a more realistic `/users` endpoint
 *  – Demonstrates basic query validation and filtering
 */
app.get(
  '/users',
  [
    // Optional `name` query param – must be alphanumeric, max 20 chars
    query('name')
      .optional()
      .isAlphanumeric()
      .isLength({ max: 20 })
      .trim()
      .escape(),
    // Optional `id` query param – must be a positive integer
    query('id')
      .optional()
      .isInt({ min: 1 })
      .toInt(),
  ],
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        // Sanitized client error, no stack trace leaked
        return res.status(400).json({ errors: errors.array() });
      }

      // Simulate a DB call – real backend would replace this
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Basic filtering logic
      const filtered = users.filter((u) => {
        if (req.query.id && u.id !== req.query.id) return false;
        if (req.query.name && !u.name.includes(req.query.name)) return false;
        return true;
      });

      res.json(filtered);
    } catch (err) {
      next(err);
    }
  }
);

/**
 *  Global error handler
 *  — Catches async errors and unhandled rejections
 */
app.use((err, req, res, next) => {
  // Log the stack trace in the server console (or use a logger)
  console.error(err.stack || err);

  // Respond with generic message; never expose stack to client
  res.status(500).json({
    error: 'Internal Server Error',
    // OPTIONAL: In dev, you might reveal err.message; handle with env check
  });
});

/**
 *  Start the HTTP server
 */
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app; // Exported for testing purposes
```

