```js
// app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');          // HTTP logging
const { body, validationResult } = require('express-validator');

const app = express();

// ---------- CONFIG ----------
const PORT = Number(process.env.PORT ?? 3000);
const TRUSTED_ORIGIN = process.env.TRUSTED_ORIGIN ?? '*';

// ---------- MIDDLEWARE ----------
app.use(helmet());                                            // security headers
app.use(cors({ origin: TRUSTED_ORIGIN }));                  // restrict CORS
app.use(rateLimit({ windowMs: 15*60*1000, max: 200 }));   // 200 req / 15 min
app.use(express.json());                                      // body parser
app.use(express.urlencoded({ extended: false }));
app.use(morgan('combined'));                                   // log access

// ---------- ROUTES ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example: `/users?limit=5`
 * Hard‑coded data is fine for demo, but validate query params
 */
app.get('/users',
  // Validate/parse query
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('limit must be 1-100'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    // Imagine we fetch from DB; for now static list
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    res.json(users);
  }
);

// ---------- ERROR HANDLING ----------
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(err.status || 500).json({ error: err.message || 'Internal Server Error' });
});

// ---------- SERVER ----------
const server = app.listen(PORT, () => {
  console.log(`🚀 Server listening on port ${PORT}`);
});

// ---------- GRACEFUL SHUTDOWN ----------
const shutdown = () => {
  console.log('💀 Shutting down...');
  server.close(() => process.exit(0));
};
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

