// ────────────────────────────────────────────────────────────────
// app.js  (boilerplate, security‑first)
// ────────────────────────────────────────────────────────────────
require('dotenv').config();                // load .env variables

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');
const morgan    = require('morgan');      // request logger
const app       = express();

// ---------- Middleware ----------
app.use(helmet());                                          // security headers
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' }));  // CORS policy
app.use(express.json());                                    // parse JSON body
app.use(morgan('combined'));                                // HTTP logging

// Rate limiter – 100 req / 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true, // return rate limit info in headers
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Routes ----------
app.get(
  '/health',
  (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  }
);

app.get(
  '/users',
  // add a fake “auth” guard, real project would check JWT/Session
  (req, res, next) => {
    // simulate authentication check
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    // Bearer will be validated later by a real auth middleware
    next();
  },
  // Optional: filter users by id via query param
  query('id').optional().isInt({ min: 1 }).withMessage('id must be a positive integer'),
  (req, res, next) => {
    // Validation response
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const id = req.query.id ? parseInt(req.query.id, 10) : null;
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // If `id` query param supplied, return single user
    res.json(id ? users.find(u => u.id === id) || { error: 'Not found' } : users);
  }
);

// ---------- Generic Error handler ----------
app.use((err, req, res, next) => {
  console.error(err);                                 // log stack
  res.status(err.status || 500).json({
    error: err.message || 'Unexpected server error',
  });
});

// ---------- Server ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server listening on port ${PORT}`);
});

module.exports = app;  // for testing frameworks (e.g., supertest)
```

