```js
// app.secure.js
// A security‑ready Express starter with best‑practice middleware

require('dotenv').config();           // Load env vars
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { check, validationResult } = require('express-validator');
const { json, urlencoded } = express;

// ------------------------------------------------------------------------
// Configuration
// ------------------------------------------------------------------------
const PORT = process.env.PORT ?? 3000;
const ALLOWED_ORIGIN = process.env.ALLOWED_ORIGIN ?? 'https://example.com';
const RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100;                  // 100 requests per window

// ------------------------------------------------------------------------
// App setup
// ------------------------------------------------------------------------
const app = express();

// ---------- Global middleware ----------
app.use(helmet());                                      // HTTP headers
app.use(helmet.contentSecurityPolicy({                // CSP
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:'],
    connectSrc: ["'self'"],
  },
}));

// Force HTTPS (works when behind a reverse proxy that sets X-Forwarded-Proto)
app.use((req, res, next) => {
  if (req.secure || req.headers['x-forwarded-proto'] === 'https') {
    next();
  } else {
    res.redirect(301, `https://${req.headers.host}${req.originalUrl}`);
  }
});

// Logging
app.use(morgan('combined'));

// Rate limiting (global)
app.use(
  rateLimit({
    windowMs: RATE_LIMIT_WINDOW_MS,
    max: RATE_LIMIT_MAX,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Body parsing
app.use(json());
app.use(urlencoded({ extended: false }));

// CORS (restrict origins; adjust ALLOWED_ORIGIN)
app.use(cors({
  origin: ALLOWED_ORIGIN,
  optionsSuccessStatus: 200,
}));

// ------------------------------------------------------------------------
// Routes
// ------------------------------------------------------------------------
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// Sample protected route – demonstrates validation
app.get('/users', [
  // In a real app you'd add auth middleware here
  check('sort', 'sort must be `name` or `id`').optional().isIn(['name', 'id']),
  check('limit', 'limit must be a number').optional().isInt({ min: 1, max: 100 }),
], (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Return sanitized error payload
    return res.status(400).json({ errors: errors.array({ onlyFirstError: true }) });
  }

  // Example data – in practice, you would query a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply optional query logic
  let sorted = users;
  if (req.query.sort) {
    const field = req.query.sort;
    sorted = users.sort((a, b) => a[field].localeCompare(b[field]));
  }

  const limit = req.query.limit ? parseInt(req.query.limit, 10) : null;
  const payload = limit ? sorted.slice(0, limit) : sorted;

  res.status(200).json(payload);
});

// ------------------------------------------------------------------------
// 404 handler
// ------------------------------------------------------------------------
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// ------------------------------------------------------------------------
// Global error handler
// ------------------------------------------------------------------------
app.use((err, req, res, next) => {
  // eslint-disable-next-line no-console
  console.error(err.stack);
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    // Never expose details in production
    ...(process.env.NODE_ENV !== 'production' && { message: err.message, stack: err.stack }),
  });
});

// ------------------------------------------------------------------------
// Start server
// ------------------------------------------------------------------------
app.listen(PORT, () => {
  // eslint-disable-next-line no-console
  console.log(`🚀 Server listening on port ${PORT}`);
});

module.exports = app;
```

