// app.js
// -----------------------------------------------------------
// Updated: Express best‑practices demo (security & error handling)
// -----------------------------------------------------------

require('dotenv').config();           // Load .env
const express = require('express');
// npm install helmet cors express-rate-limit express-async-errors express-validator morgan
const helmet = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');
// eslint-disable-next-line no-unused-vars
require('express-async-errors'); // automatically async catches
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// --------- Middleware ---------------------------------------------------------------------
// 1️⃣ Security headers
app.use(helmet());

// 2️⃣ CORS – restrict to whitelisted origins
const whitelist = ['https://yourdomain.com']; // <-- adjust
const corsOptions = {
  origin(origin, callback) {
    if (!origin || whitelist.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// 3️⃣ Rate limiting (5 req/min per IP)
app.use(
  rateLimit({
    windowMs: 1 * 60 * 1000,
    max: 5,
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, try again later.' },
  })
);

// 4️⃣ Logging
app.use(morgan('combined'));

// 5️⃣ Body parsing (JSON + URL encoded)
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// --------- Routes -------------------------------------------------------------------------

// 1️⃣ Health‑check (explicit status, no injection risk)
app.get('/health', async (req, res) => {
  res.status(200).json({
    success: true,
    data: {
      status: 'ok',
      timestamp: new Date().toISOString(),
    },
  });
});

// 2️⃣ Users – demo of query validation & JSON response shape
app.get(
  '/users',
  // Example: ?page=1&limit=10
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  async (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad request
      return res.status(400).json({
        success: false,
        error: 'Invalid query parameters',
        details: errors.array(),
      });
    }

    const { page = 1, limit = 2 } = req.query;

    // Mimic a paginated data source
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const start = (page - 1) * limit;
    const paginated = users.slice(start, start + limit);

    res.status(200).json({
      success: true,
      data: paginated,
    });
  }
);

// --------- Error handling -----------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
const errorHandler = (err, req, res, next) => {
  // Logging
  console.error(`[${new Date().toISOString()}] ${err.stack || err}`);

  // Avoid leaking stack trace in prod
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.statusCode || 500).json({
    success: false,
    error: err.message || 'Internal Server Error',
    ...(isProduction ? {} : { stack: err.stack }),
  });
};

app.use(errorHandler);

// --------- Server startup -----------------------------------------------------------------------

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

module.exports = app;
```

