## 3. Suggested Refactored `app.js`

> *(This example shows a minimal but production‑ready setup. Adjust as needed.)*

```js
// app.js – Lightweight, secure Express starter
require('dotenv').config();          // Load .env only in dev

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

/* ---------- 1️⃣  SECURITY MIDDLEWARE ---------- */

// Reduce attack surface
app.use(helmet());

// Basic CORS: adjust `origin` per domain you want to support
app.use(cors({ origin: process.env.CORS_ORIGIN || 'http://localhost:3000' }));

// Logging
app.use(morgan('combined'));

/* ---------- 2️⃣  RATE LIMITING ---------- */

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,   // 15 mins
  max: 100,                   // 100 requests per window per IP
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

/* ---------- 3️⃣  ROUTES ---------- */

app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    next(err); // will be caught by error handler
  }
});

app.get('/users', (req, res, next) => {
  try {
    // In real apps this data will come from a DB
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (err) {
    next(err);
  }
});

/* ---------- 4️⃣  ERROR HANDLER ---------- */

app.use((err, req, res, next) => {
  console.error('⚠️  Internal error: ', err);                // Log stack trace

  // Do not expose stack traces to clients
  res.status(500).json({
    error: 'Internal Server Error',
  });
});

/* ---------- 5️⃣  SERVER STARTUP ---------- */

const PORT = process.env.PORT || 3000;

// `app.listen` returns the http.Server instance.  Keep it
// handy for graceful shutdowns in the future.
const server = app.listen(PORT, () => {
  console.log(`🏁 Server running on port ${PORT}`);
});

module.exports = { app, server }; // Export server to allow tests to close it
```

> **Notes on the changes**

1. **`helmet()`** covers a lot of header‑level hardening automatically.
2. **Rate limiting** turns a naive `GET /users` into a more resilient endpoint.
3. **CORS** avoids accidental data leaks to untrusted origins.
4. **Comprehensive error handler** ensures clients never see a stack trace.
5. **Logging** through `morgan` gives you plain‑text logs that can be shipped to Elasticsearch, CloudWatch, etc.
6. **Graceful server export** (`module.exports = { app, server }`) lets automated tests `server.close()` without orphaned processes.

