/// Express application with security best practices
/// Includes helmet, morgan, rate limiter, and error handling middleware

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

// Basic security middlewares
app.use(helmet());
// Configure CORS - allow only specific origins if needed
app.use(cors({ origin: ['http://localhost:3000'], optionsSuccessStatus: 200 }));

// Parse JSON bodies safely
app.use(express.json({ limit: '1mb' }));

// Request logging
app.use(morgan('combined'));

// Rate limiting to mitigate brute‑force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Routes
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app this would call a database, here we return a static payload
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.status(200).json(users);
});

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

