// app.js – Improved version with error handling, input validation, and security best practices
// ============================================================================
// This file contains a minimal Express application which demonstrates
// common patterns for production‑ready Node.js services.  The original
// repository had only a few simple routes and lacked any form of error
// handling, validation or security hardening.  The rewritten code below
// addresses those gaps while keeping the overall behaviour identical.
// ============================================================================

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
const packageJson = require('./package.json');

const app = express();

// -------- Environment & configuration -------------------------------------
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
const ENV = process.env.NODE_ENV || 'development';

// A very small whitelist for CORS – adjust as necessary.
const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests with no origin (e.g., mobile apps, curl)
    if (!origin) return callback(null, true);
    const allowedOrigins = ['https://example.com', 'http://localhost:3000'];
    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS policy')); // Will be caught by global error handler
    }
  },
  optionsSuccessStatus: 200,
};

// -------- Middleware -------------------------------------------------------
app.use(helmet()); // Set HTTP security headers
app.use(cors(corsOptions));
app.use(rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
}));
app.use(morgan('combined')); // Request logging
app.use(express.json({ limit: '10kb' })); // Parse JSON bodies with size limit
app.use(express.urlencoded({ extended: false }));

// -------- Routes -----------------------------------------------------------

/**
 * Health‑check endpoint.
 * It returns the application status and a timestamp.  Additional
 * diagnostics (e.g., uptime, memory usage) could be added here.
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    node: process.version,
    env: ENV,
  });
});

/**
 * A simple “users” endpoint.  The route is intentionally minimal – in a
 * real application you would fetch data from a database or other backend.
 * We still demonstrate how to validate request parameters to guard
 * against malformed input or injection attempts even though no body is
 * currently expected.  This placeholder can easily be extended.
 */
app.get('/users', async (req, res, next) => {
  try {
    // In a realistic setup, validation of query parameters or headers
    // would occur here.  For demonstration we just return a static list.
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (err) {
    next(err);
  }
});

// -------- Error handling ---------------------------------------------------

/**
 * 404 Handler – catches unknown routes.
 */
app.use((req, res, next) => {
  const err = new Error('Route not found');
  err.status = 404;
  next(err);
});

/**
 * Global error handler.  Only stack traces are returned in "development"
 * mode to avoid leaking sensitive information in production.
 */
app.use((err, req, res, next) => {
  if (res.headersSent) {
    return next(err);
  }

  const status = err.status || 500;
  const response = {
    error: {
      message: err.message,
    },
  };

  if (ENV === 'development') {
    response.error.stack = err.stack;
  }

  res.status(status).json(response);
});

// -------- Export & boot ---------------------------------------------------

const startServer = () => {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${ENV}`);
    console.log(`Package: ${packageJson.name}@${packageJson.version}`);
  });
};

// If this module is run directly, start the server.
if (require.main === module) {
  startServer();
}

module.exports = { app, startServer };

