    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100'),

  (req, res, next) => {
    // Handle validation errors
    const errors = validationResult(req)
    if (!errors.isEmpty()) {
      logger.warn('Validation failed', { errors: errors.array(), ip: req.ip })
      return res.status(400).json({
        status: 400,
        error: 'Invalid query parameter',
        details: errors.array()
      })
    }

    // Dummy data – would normally be fetched from a DB
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]

    // Respect `limit` if present
    const limit = parseInt(req.query.limit, 10) || users.length
    return res.status(200).json(users.slice(0, limit))
  }
)

// Graceful error starter for the endpoint that might throw
app.get('/example-async', async (req, res, next) => {
  try {
    // Simulated async operation that could error
    const data = await Promise.reject(new Error('boom'))
    res.json(data)
  } catch (err) {
    next(err)           // Pass to the global error handler
  }
})

// ─────────────────────────────────────────────────────────────
// 4️⃣  Global error handler
// ─────────────────────────────────────────────────────────────
app.use((err, req, res, next) => {
  // Log the error stack only on the server console
  logger.error('Unhandled error', { err: err.stack, ip: req.ip, path: req.path })

  // Never expose the stack trace to the client
  res.status(err.status || 500).json({
    status: err.status || 500,
    error: err.message || 'Internal Server Error'
  })
})

// ─────────────────────────────────────────────────────────────
// 5️⃣  Startup
// ─────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000
app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`)
})

// Export for tests / serverless
module.exports = app
```

### What this version does

| Feature | Implementation |
|---------|----------------|
| **Environment‑driven port** | `process.env.PORT` |
| **Secure headers** | `helmet()` |
| **CORS** | `cors({origin:false})` by default. Override via `CORS_ORIGIN`. |
| **Rate limiting** | 100 req / 15 min per IP. |
| **Request body limits** | 100 KB for JSON & URL‑encoded body. |
| **Logging** | Winston + Morgan. |
| **Input validation** | `express-validator` on `/users` (example). |
| **Error handling** | Global error middleware logs stack, returns generic message. |
| **Unhandled promise rejection guard** | `app.use()` error handler + `process.on('unhandledRejection')` (caveat – that's optional; you can add it too). |

---

## 4. Minor notes

1. **Add a .env.example** file listing needed environment variables (`PORT`, `CORS_ORIGIN`, etc.).
2. If the API will grow, consider splitting routers (`routes/users.js`) and moving the validation logic (with a dedicated validator file).
3. Attach a health‑check with the `readiness` & `liveness` probe semantics if you deploy to Kubernetes.
4. If you later add POST/PUT endpoints, validate the body with `express‑validator`/`joi` and perform input sanitization (e.g., `mongo-sanitize` if using MongoDB).

